/* The cowbell sample bank. samples.c is generated by tools/make_samples.py: do not edit it by hand.
 *
 * Format: mono, 44,100 Hz (or 22,050: rshift), 4-bit IMA ADPCM, two samples a byte, the LOW nibble first. The decoder starts
 * with predictor 0 and step index `index0`; the standard IMA tables (89 steps, index changes
 * -1 -1 -1 -1 2 4 6 8). A sample plays only forwards from its start. */
#ifndef CB_SAMPLES_H
#define CB_SAMPLES_H
#include <stdint.h>

typedef struct {
    char name[10];          /* up to 9 characters, upper case: shown on the screen */
    uint8_t root;           /* the MIDI note it sounds closest to (KEYS mode plays this at C4) */
    uint8_t gain;           /* playback gain, Q7 (128 = 1.0): evens out loudness across the bank */
    uint8_t index0;         /* the ADPCM decoder's starting step index (0..88) */
    uint8_t rshift;         /* the sample rate: 44,100 Hz >> rshift (0: 44.1 kHz, 1: 22.05 kHz) */
    uint32_t n;             /* length in frames, at its own rate */
    const uint8_t *data;    /* (n + 1) / 2 bytes */
} cb_sample_t;

extern const cb_sample_t CB_SAMPLES[];
extern const uint32_t CB_N_SAMPLES;

#endif
